syntax:
pthread_once_t once = PTHREAD_ONCE_INIT; // Initialization
pthread_once(&once, &init); // Call init only once
// ... other thread synchronization primitives (mutexes, condition variables, semaphores)

code_example:
#include <pthread.h>
static pthread_once_t once = PTHREAD_ONCE_INIT;
void init(void) {
  // Initialization code to be executed only once
  printf("Initialization performed\n");
}
void *thread_func(void *arg) {
  pthread_once(&once, &init);
  // Access shared resources here
  return NULL;
}
int main() {
  pthread_t thread1, thread2;
  pthread_create(&thread1, NULL, thread_func, NULL);
  pthread_create(&thread2, NULL, thread_func, NULL);
  pthread_join(thread1, NULL);
  pthread_join(thread2, NULL);
  return 0;
}
